// --- UNIFORMS ---
uniform sampler2D uPreviousFrame;
uniform vec2 uResolution;
uniform float uTime;

// --- SETTINGS ---
uniform float uThreshold;     // 0.1  (Sensitivity: Lower = More melting)
uniform float uLength;        // 0.6  (How long the drips are)
uniform float uDensity;       // 500.0 (Width of lines. Higher = Thinner/Finer)
uniform float uOpacity;       // 1.0  (Blend mix: 1.0 = Full Effect)

// --- HELPERS ---

float getLuma(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

// Random noise (optional, used for slight length variation)
float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {

    vec2 pixel = 1.0 / uResolution;

    // 1. GRID QUANTIZATION (Create the "Columns")
    // We lock the X coordinate to a grid to create sharp vertical lines
    // typical of the "Pixel Sort" aesthetic.
    float gridX = floor(uv.x * uDensity) / uDensity;

    // 2. RANDOMIZE LENGTH PER COLUMN
    // This makes some lines drip further than others, like the reference.
    float colNoise = hash(vec2(gridX, 1.0));
    float loopLength = uLength + (colNoise * 0.2); // Add 20% variance

    // 3. THE SORTING LOOP
    // We look UPWARDS (positive Y) to find bright pixels that should have "fallen" down here.

    vec4 bestColor = texture2D(uPreviousFrame, uv); // Start with current pixel
    float maxEnergy = 0.0;

    // We use the luminance of the current pixel as the baseline "Energy"
    // If we find a brighter pixel above, it overwrites this one.
    float currentLuma = getLuma(bestColor.rgb);

    // Check if the current pixel is bright enough to start a drip itself
    if (currentLuma > uThreshold) {
        maxEnergy = currentLuma; 
    }

    // Sample count: Determines quality. 
    // 40-60 is usually good for long drips without killing the GPU.
    float samples = 60.0; 

    for (float i = 1.0; i <= samples; i++) {
        // Calculate normalized distance (0.0 to 1.0) relative to max length
        float t = i / samples;

        // Convert 't' to actual Y distance
        float yOffset = t * loopLength;

        // Sample Position: Look UP
        vec2 samplePos = vec2(gridX, uv.y + yOffset);

        // Bounds check (don't read off screen)
        if (samplePos.y <= 1.0) {
            vec4 col = texture2D(uPreviousFrame, samplePos);
            float luma = getLuma(col.rgb);

            // LOGIC:
            // A pixel "falls" if it is bright (luma > threshold).
            // However, it loses "energy" as it falls (luma - yOffset).
            // We pick the pixel that has the highest remaining energy at this location.

            if (luma > uThreshold) {
                // Calculate Energy:
                // Brighter pixels fall further. 
                // We multiply yOffset by 1.5 to create "friction" so they eventually stop.
                float energy = luma - (yOffset * 1.5);

                if (energy > maxEnergy) {
                    maxEnergy = energy;
                    bestColor = col;
                }
            }
        }
    }

    // 4. BLEND
    // If opacity is lower, we mix back the original clean image
    vec4 original = texture2D(uPreviousFrame, uv);
    vec4 finalColor = mix(original, bestColor, uOpacity);

    outputColor = finalColor;
}
